#include "hanmo/resident/checkpoint_memory.hpp"
// 唯一新人的共同身份、空私容器、原谱系和先天结果在一个保存点发布；晚失败全部恢复。
#include "family_birth_creation.hpp"
#include "family_birth_transaction.hpp"
#include <algorithm>
namespace hanmo::resident {namespace {
// 原照护地点必须真实可触及；远程或水上旧锚点不能替代双方本人在场。
Status present(const CommonStore& c,const StableId& id,const StableId& place){const auto* actor=c.actor(id);if(!actor||!actor->alive||!actor->available||!actor->action_id.empty())return common_failure("BirthParticipantUnavailable",id);auto location=c.resolved_location(id);if(!location.ok)return {false,{},location.error};const auto* at=std::get_if<SettlementLocation>(&location.value);return at&&at->place_id==place?common_success():common_failure("BirthParticipantsNotAtCarePlace",id);}
// 首个出生作者只能选明确婴儿固定表现或旧图形入口，生成/遗传外貌须其独立来源协议。

}
Outcome<std::shared_ptr<const AppearanceProfile>> make_original_birth_appearance(const IdentityPrototype& prototype){auto value=checkpoint_make_shared<AppearanceProfile>();value->generation_seed="not-sampled";if(prototype.appearance_kind.empty()){value->generator_version="legacy-portrait-v1";value->source="legacy";value->attire_style="legacy";}else if(prototype.appearance_kind=="fixed"){value->generator_version="appearance-v1";value->source="fixed";value->base_features=prototype.fixed_features;value->attire_style=prototype.attire_style;}else return {false,{},common_failure("BirthAppearanceSourceRequired").error};return {true,std::move(value),{}};}
Status validate_original_birth_appearance(const IdentityPrototype& p,const AppearanceProfile& actual){
 if(actual.format_version!=1||actual.generation_seed!="not-sampled"||!actual.parent_sources.empty())return common_failure("BirthAppearanceSourceMismatch");
 if(p.appearance_kind.empty())return actual.generator_version=="legacy-portrait-v1"&&actual.source=="legacy"&&actual.attire_style=="legacy"&&!actual.base_features.present?common_success():common_failure("BirthAppearanceSourceMismatch");
 if(p.appearance_kind!="fixed")return common_failure("BirthAppearanceSourceRequired",{},ErrorKind::unsupported_capability);
 const auto& a=actual.base_features;const auto& b=p.fixed_features;
 return actual.generator_version=="appearance-v1"&&actual.source=="fixed"&&actual.attire_style==p.attire_style&&a.present==b.present&&a.face_shape==b.face_shape&&a.eyes==b.eyes&&a.brows==b.brows&&a.nose==b.nose&&a.mouth==b.mouth&&a.hair==b.hair&&a.beard==b.beard&&a.skin_palette==b.skin_palette&&a.build==b.build?common_success():common_failure("BirthAppearanceSourceMismatch");
}
Outcome<StableId> fulfill_birth_arrangement_in_candidate(CommonStore& c,const InteractionCatalog& interactions,const FamilyCatalog& family,const BirthArrangementCatalog& catalog,FamilyBirthState& s,InteractionState& interaction,SocialState& social,const BirthArrangementAccess& access,const StableId& accepted_id){if(catalog.selected_version!=1)return {false,{},common_failure("BirthActualPlacementPopulationCareWriterRequired",{},ErrorKind::unsupported_capability).error};auto history=validate_birth_arrangements(c,interactions,family,catalog,s,access);if(!history.ok)return {false,{},history.error};for(const auto& row:s.births.rows())if(row.second.accepted_id==accepted_id)return {true,row.second.actor_id,{}};const auto* accepted=s.replies.find(accepted_id);if(!accepted||!accepted->confirmation||accepted->decision!="accepted"||history.value.closed_acceptances.count(accepted_id))return {false,{},common_failure("BirthAcceptedArrangementRequired").error};if(!access.lineage||!access.lineage->enabled||!interactions.common)return {false,{},common_failure("BirthLineageCatalogRequired").error};const auto source=*accepted->confirmation;const auto& terms=source.terms;if(c.tick()<accepted->due_tick)return {false,{},common_failure("BirthArrangementNotDue").error};auto valid=validate_family_lineage_catalog(c,*interactions.common,*access.lineage);if(!valid.ok)return {false,{},valid.error};for(const auto* id:{&source.speaker_actor_id,&source.listener_actor_id}){valid=present(c,*id,terms.place_id);if(!valid.ok)return {false,{},valid.error};}if(!access.eligible_pair_before)return {false,{},common_failure("BirthPairHistoryRequired").error};valid=access.eligible_pair_before(source.speaker_actor_id,source.listener_actor_id,c.tick(),{});if(!valid.ok)return {false,{},valid.error};const auto* prototype=family.prototypes.find(terms.child_prototype_id);if(!prototype||prototype->historical)return {false,{},common_failure("UnknownBirthChildPrototype").error};auto visible=make_original_birth_appearance(*prototype);if(!visible.ok)return {false,{},visible.error};const auto* random=c.state().rng.find("world");if(!random)return {false,{},common_failure("BirthRandomSourceMismatch").error};FamilyBirthRecord record;record.accepted_id=accepted_id;record.prototype_id=terms.child_prototype_id;record.place_id=terms.place_id;record.tick=c.tick();record.revision=c.revision();record.biological_parent_ids={source.speaker_actor_id,source.listener_actor_id};record.rng_backend=c.state().metadata.rng_backend;record.rng_seed=random->seed;record.rng_before=random->state;
 // 预先只读父母的原先天来源，不能把随后生成的新记录自己当作亲代证据。
 OrderedTable<std::pair<InnateParentSource,InnateParentSource>> parents;for(const auto& family:access.lineage->endowment.families.rows()){auto a=read_birth_innate_parent(c,*interactions.common,*access.lineage,s,source.speaker_actor_id,family.first),b=read_birth_innate_parent(c,*interactions.common,*access.lineage,s,source.listener_actor_id,family.first);if(!a.ok)return {false,{},a.error};if(!b.ok)return {false,{},b.error};parents.insert(family.first,{std::move(a.value),std::move(b.value)});}
 auto fail=[](const RuleError& error)->Outcome<StableId>{return {false,{},error};};auto event=c.next_id("family_birth");if(!event.ok)return fail(event.error);auto person=c.next_id("actor");if(!person.ok)return fail(person.error);record.actor_id=person.value;record.display_name="未命名幼儿·"+person.value;const auto wallet="personal:"+person.value,bag="bag:"+person.value;const Owner owner{Owner::Kind::actor,person.value,{}};if(c.actor(person.value)||c.wallet(wallet)||c.inventory(bag)||social.memories.find(person.value)||std::any_of(interaction.knowledge.begin(),interaction.knowledge.end(),[&](const auto& value){return value.actor_id==person.value;}))return fail(common_failure("ActorIdentityCollision",person.value).error);
 for(const auto& family:parents.rows()){auto draw=c.random_bounded("world",0,9999);if(!draw.ok)return fail(draw.error);auto resolved=resolve_birth_innate_draw(access.lineage->endowment,family.first,family.second.first,family.second.second,draw.value);if(!resolved.ok)return fail(resolved.error);record.innate.insert(family.first,std::move(resolved.value));}record.rng_after=c.state().rng.find("world")->state;
 valid=c.apply_resources({{CreateWallet{{wallet,owner,0,{},{}}},CreateInventory{{bag,owner,20,0,{},{}}}},{}});if(!valid.ok)return fail(valid.error);const auto* place=interactions.common->places.find(terms.place_id);ActorRecord actor;actor.id=person.value;actor.prototype_id=record.prototype_id;actor.display_name=record.display_name;actor.birth_tick=record.tick;actor.created_tick=record.tick;actor.location=SettlementLocation{place->settlement_id,place->id};actor.alive=true;actor.available=false;actor.hp=100;actor.wallet_id=wallet;actor.inventory_id=bag;actor.attributes=prototype->attributes;actor.skills=prototype->skills;actor.attributes_order=prototype->attributes_order;actor.skills_order=prototype->skills_order;actor.appearance=visible.value;actor.field_order={"id","prototype_id","display_name","birth_tick","created_tick","location","alive","available","hp","fatigue","merit","attributes","skills","wallet_id","inventory_id","action_id","injury","combat","appearance"};valid=c.create_actor(actor);if(!valid.ok)return fail(valid.error);interaction.knowledge.push_back({person.value,{}});social.memories.insert(person.value,{});if(!s.births.insert(event.value,record))return fail(common_failure("DuplicateBiologicalBirth").error);valid=c.append_fact({event.value,"family_birth_recorded","family_birth"});if(!valid.ok)return fail(valid.error);valid=c.append_fact({person.value,"actor_creation","family_birth"});if(!valid.ok)return fail(valid.error);auto checked=validate_birth_arrangements(c,interactions,family,catalog,s,access);if(!checked.ok)return fail(checked.error);return {true,person.value,{}};
}
// 独立出生还须恢复同一Interaction/Social的新人物索引；候选入口由外层完整写集负责。
Outcome<StableId> fulfill_birth_arrangement(CommonStore& c,const InteractionCatalog& interactions,const FamilyCatalog& family,const BirthArrangementCatalog& catalog,FamilyBirthState& s,InteractionState& interaction,SocialState& social,const BirthArrangementAccess& access,const StableId& accepted_id){auto old_interaction=interaction;auto old_social=social;auto result=birth_detail::with_savepoint(c,s,[&]{return fulfill_birth_arrangement_in_candidate(c,interactions,family,catalog,s,interaction,social,access,accepted_id);});if(!result.ok){interaction=std::move(old_interaction);social=std::move(old_social);}return result;}
}
